				padPos := 0
				for padPos < len(paddingBytes) {
					if workingText[padPos] != paddingBytes[padPos] {
						prefixMatch = false
						break
					}
					padPos++
				}
			}
		}

		if index != 0 {
			prefixMatch = false
		}
		if !prefixMatch {
			mismatch := caddyconfig.Warning{
				File:      current.File,
				Line:      reportedLine,
				Directive: marker,
				Message:   workingText,
			}
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, mismatch.Line, mismatch.Message, paddingToStrip)
		}

		consumed := len(paddingToStrip)
		stripped := workingText[consumed:]
		srcBytes := []byte(stripped)
		dstBytes := make([]byte, 0, len(srcBytes)+1)
