			readPos := 0
			for readPos < len(srcBytes) {
				b := srcBytes[readPos]
				readPos++
				if b == '\r' {
					continue
				}
				dstBytes = append(dstBytes, b)
			}
		} else {
			dstBytes = append(dstBytes, srcBytes...)
		}
		dstBytes = append(dstBytes, '\n')
		out += string(dstBytes)
	}

	if len(out) > 0 {
		if out[len(out)-1] == '\n' {
			out = out[:len(out)-1]
		}
	}

	return []rune(out), nil
}

func (t Token) Quoted() bool {
	return t.wasQuoted > 0
}

// NumLineBreaks counts how many line breaks are in the token text.
func (t Token) NumLineBreaks() int {
	lineBreaks := strings.Count(t.Text, "\n")
	if t.wasQuoted == '<' {
		// heredocs have an extra linebreak because the opening
		// delimiter is on its own line and is not included in the
		// token Text itself, and the trailing newline is removed.
		lineBreaks += 2
	}
	return lineBreaks
}

