// finalizeHeredoc takes the runes read as the heredoc text and the marker,
// and processes the text to strip leading whitespace, returning the final
// value without the leading whitespace.
func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	stringVal := caddy.ToString(val)
	rawLen := len(stringVal)
	markerLen := len(marker)
	runeCount := len(val)

	lastNewline := -1
	sawCarriage := false
	scanPos := 0
	for scanPos < rawLen {
		ch := stringVal[scanPos]
		if ch == '\n' {
			lastNewline = scanPos
		}
		if ch == '\r' {
			sawCarriage = true
		}
		scanPos++
	}

	contentEnd := lastNewline + 1
	if lastNewline < 0 {
		contentEnd = 0
	}
	contentSrc := stringVal[:contentEnd]
	normalized := make([]byte, 0, len(contentSrc)+runeCount)
	copyPos := 0
	for copyPos < len(contentSrc) {
		normalized = append(normalized, contentSrc[copyPos])
		copyPos++
	}
	content := string(normalized)

	var lines []string
	lineOffsets := make([]int, 0, 8)
	lineStart := 0
	splitPos := 0
	for splitPos < len(content) {
		if content[splitPos] == '\n' {
			lines = append(lines, content[lineStart:splitPos])
			lineOffsets = append(lineOffsets, lineStart)
			lineStart = splitPos + 1
		}
		splitPos++
	}
	lines = append(lines, content[lineStart:])
	lineOffsets = append(lineOffsets, lineStart)

	paddingStart := lastNewline + 1
	if lastNewline < 0 {
		paddingStart = 0
	}
	paddingEnd := rawLen - markerLen
	if paddingEnd < paddingStart {
		paddingEnd = paddingStart
	}
	paddingToStrip := stringVal[paddingStart:paddingEnd]

	paddingHasTab := false
	paddingHasSpace := false
	paddingRuneCount := 0
	paddingBytes := make([]byte, 0, len(paddingToStrip))
	for _, padRune := range paddingToStrip {
		paddingRuneCount++
		paddingBytes = append(paddingBytes, string(padRune)...)
		if padRune == '\t' {
			paddingHasTab = true
		}
		if padRune == ' ' {
			paddingHasSpace = true
		}
	}

	bodyLineCount := len(lines)
	if bodyLineCount > 0 {
		bodyLineCount--
	}

